import React from 'react';
import axios from 'axios';

export default class NewInventory extends React.Component {
    url = 'http://localhost:5000';

    submitHandler = (e) => {
        e.preventDefault();
        let formData = new FormData(e.target);
        axios.post(`${this.url}/inventory`, {
                data: formData
                })
            .then(response => {
                console.info(response);
                e.target.reset();
            })
            .catch(error => console.error(error));
    }

    render() {
        return (
            <div>                
                <h1>ADD NEW INVENTORY ITEM</h1>
                <form name="inventoryItem">                               
                    <label htmlFor="">Item Name</label>
                    <input name="itemName" />

                    <label>Description</label>
                    <textarea name="description" placeholder="Please enter a brief description..."></textarea>            

                    <label>Category</label>
                    <select name="category">
                        <option value="">f</option>
                    </select>

                    <input type="radio" name="status" id="in-stock" value="In stock" />
                    <label htmlFor="in-stock">Status</label>

                    <input type="radio" name="status" id="out-of-stock" value="Out of stock"/>
                    <label htmlFor="out-of-stock">Status</label>

                    <label>Quantity</label>
                    <input type="number" value="0"/>

                    <label>Warhouse Name</label>
                    <select>
                        <option value="">f</option>
                        <option value="">f</option>
                        <option value="">f</option>
                    </select>
                    <input onClick={this.submitHandler}>+Add Item</input>
                    <input type="reset" Cancel/>
                </form>

            </div>
        );
    }
}
